"""Prepare additive source identities and bounded inspection receipts."""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[2]; HERE=Path(__file__).resolve().parent
resources=[]
def add(id,title,authors,edition,year,kind,url,domains,locators,scope,limits,reason,local=None,method=None):
    inspection={'date':'2026-10-10','method':method or 'Primary web text/PDF bounded passages inspected; source identity and applicability checked','scope':scope,'limits':limits,'evidence_urls':[url],'local_document_id':None,'local_sha256':None}
    access='Primary online source; exact revision or accessed date recorded'
    if local:
        p=next(p for p in Path('F:/Knowledge/Library').rglob('*.pdf') if local in str(p) and '/_old/' not in p.as_posix())
        m=json.loads((p.parent/'metadata.json').read_text(encoding='utf-8-sig'))
        inspection.update(local_document_id=m['file_id'],local_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),local_path=p.as_posix())
        access='Held local PDF; selected text passages extracted with pdftotext and inspected; no complete-book review claim'
    r={'id':id,'title':title,'authors':authors,'edition':edition,'year':year,'kind':kind,'url':url,'access':access,'domains':domains,'role':'primary','reason':reason,'prerequisites':['Selected module entry check'],'locators':locators,'assignable':True,'inspection':inspection}
    work=hashlib.sha256((title+'|'+','.join(authors)).encode()).hexdigest()[:16];ed=hashlib.sha256((work+'|'+edition).encode()).hexdigest()[:16]
    r.update(work_id='W-'+work,edition_id='E-'+ed,inspection_ids=['I-'+hashlib.sha256(json.dumps(inspection,sort_keys=True).encode()).hexdigest()[:16]])
    resources.append(r)

